-- 0086_assess_prep_myp4.sql
-- MYP 4 Mathematics — Formative Assessment: Statistics
-- Assess Prep formative: typed answers only, 2 hint levels per question/part,
-- native SVG diagrams. Fixed UUIDs + ON CONFLICT DO NOTHING: idempotent.
begin;

insert into quizzes (id, organization_id, title, description, status, settings, created_by)
values ('b4000000-0000-4000-8000-000000000001', '0a400000-0000-4000-8000-000000000001', 'MYP 4 Mathematics — Formative Assessment: Statistics', 'Grade 9 · MYP 4 · Mathematics · Formative (Assess Prep). Statistics only: classification of data, stem-and-leaf diagrams, measures of centre and spread, grouped data, cumulative frequency, histograms and standard deviation. Type every answer — there are no options to choose from.', 'published',
        '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"formative","grade_level":"9","curriculum":"MYP 4","subject":"Mathematics","duration_minutes":45,"total_marks":50,"source":"assess-prep-myp4-formative"}'::jsonb, '3c3ed712-f409-4aa1-a645-816418e22ec4')
on conflict (id) do nothing;

insert into questions (id, organization_id, type, prompt, prompt_doc, explanation, explanation_doc,
                       points, difficulty, topic, subtopic, tags, status, config, created_by,
                       curriculum, curriculum_course, subject_id, review_status, creation_method, class_id)
select ('b4000000-0000-4000-8000' || lpad((100 + (x->>'n')::int)::text, 12, '0'))::uuid,
       '0a400000-0000-4000-8000-000000000001', x->>'t', x->>'p', x->'d', x->>'e', null,
       (x->>'m')::numeric, x->>'df', x->>'tp', x->>'st',
       array['MYP 4', 'Mathematics', 'formative', 'assess-prep'], 'published', x->'cfg', '3c3ed712-f409-4aa1-a645-816418e22ec4',
       'MYP', 'MYP 4 Mathematics', '0a400000-0000-4000-8000-000000000030', 'approved', 'manual', '0a400000-0000-4000-8000-000000000109'
  from jsonb_array_elements('[{"n":1,"t":"assess_parts","p":"For each variable, type the correct data type: qualitative, discrete or continuous.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For each variable, type the correct data type: qualitative, discrete or continuous."}]}]},"e":"Number of siblings takes whole-number values you count, so it is discrete (quantitative). Heights are measured and can take any value in a range, so continuous. Favourite colour is a category, so qualitative.\n\nHint for next time: Ask: do you count it, measure it, or name it?","m":3,"df":"easy","tp":"classification of data","st":"classifying variables","cfg":{"source":"assess-prep-myp4-formative","question_number":1,"myp_criterion":"A","next_time_hint":"Ask: do you count it, measure it, or name it?","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Number of siblings","kind":"text","points":1,"hints":["Ask: do you count it, measure it, or name it?","Counted whole numbers are a particular data type."],"accepted":["discrete","quantitative discrete","discrete quantitative"]},{"id":"b","label":"(b)","prompt":"Height of students in cm","kind":"text","points":1,"hints":["Ask: do you count it, measure it, or name it?","Measured values can fall anywhere in a range."],"accepted":["continuous","quantitative continuous","continuous quantitative"]},{"id":"c","label":"(c)","prompt":"Favourite colour","kind":"text","points":1,"hints":["Ask: do you count it, measure it, or name it?","A named category is not a number at all."],"accepted":["qualitative"]}]}},{"n":2,"t":"open_ended","p":"A student writes: \"The time taken to travel to school is discrete because the clock shows whole minutes.\" In 1–2 sentences, explain whether the student is correct. (Marked by your teacher against the rubric.)","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A student writes: \"The time taken to travel to school is discrete because the clock shows whole minutes.\" In 1–2 sentences, explain whether the student is correct. (Marked by your teacher against the rubric.)"}]}]},"e":"The student is wrong. Travel time is a measurement that can take any value (25.4 minutes, 25.43 minutes…); recording it to the nearest minute only rounds a continuous variable, it does not make the underlying data discrete.\n\nHint for next time: Think about the values time can take BETWEEN two whole minutes.","m":2,"df":"medium","tp":"classification of data","st":"explain: discrete vs continuous","cfg":{"source":"assess-prep-myp4-formative","question_number":2,"myp_criterion":"C","next_time_hint":"Think about the values time can take BETWEEN two whole minutes.","assessment_style":"assess_prep_typed","hints":["Think about the values time can take BETWEEN two whole minutes.","Decide whether the data are counted or measured, whatever the clock displays."],"marking_criteria":"2 marks. 1: states the student is wrong / time is continuous. 1: justifies that time is measured and can take any value in a range (rounding to minutes does not make it discrete).","response_tools":["rich_text","math","table"],"response_requirement":"text","response_guidance":"Write 1–2 clear sentences. Give your conclusion first, then justify it."}},{"n":3,"t":"assess_parts","p":"The stem-and-leaf diagram shows the test marks of a class (key: 3 | 5 means 35 marks).","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The stem-and-leaf diagram shows the test marks of a class (key: 3 | 5 means 35 marks)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"stem_leaf","title":"Test marks","stemKey":"3 | 5 means 35","stemRows":[{"stem":"2","leaves":["1","4","7"]},{"stem":"3","leaves":["0","2","5","5","8"]},{"stem":"4","leaves":["1","3","6"]},{"stem":"5","leaves":["0","2"]}]}}}]},"e":"The diagram has 13 leaves, so 13 students. The greatest mark is 52. The median is the middle value (position 7 of 13), which is 35.\n\nHint for next time: Each leaf is one student.","m":2,"df":"easy","tp":"stem-and-leaf diagrams","st":"reading a stem-and-leaf diagram","cfg":{"source":"assess-prep-myp4-formative","question_number":3,"myp_criterion":"A","next_time_hint":"Each leaf is one student.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many students took the test?","kind":"numeric","points":1,"hints":["Each leaf is one student.","Count all the leaves in the diagram."],"answer":13,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find the median mark.","kind":"numeric","points":1,"hints":["The median is the middle value when the data are in order — the diagram is already ordered.","Count in from either end to the middle leaf."],"answer":35,"tolerance":0}]}},{"n":4,"t":"assess_parts","p":"The back-to-back stem-and-leaf diagram compares the marks of Class A (left) and Class B (right). Key: 2 | 1 | 4 means 12 for Class A and 14 for Class B.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The back-to-back stem-and-leaf diagram compares the marks of Class A (left) and Class B (right). Key: 2 | 1 | 4 means 12 for Class A and 14 for Class B."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"stem_leaf","title":"Marks: Class A (left) vs Class B (right)","stemKey":"2 | 1 | 4 means 12 (A) and 14 (B)","leftTitle":"Class A","rightTitle":"Class B","stemRows":[{"stem":"1","left":["8","5","2"],"leaves":["1","4","6"]},{"stem":"2","left":["9","6","4","1"],"leaves":["0","2","5","8"]},{"stem":"3","left":["7","3"],"leaves":["1","4","9"]}]}}}]},"e":"Class A marks in order: [12, 15, 18, 21, 24, 26, 29, 33, 37]. Their median is 24. Class B: [11, 14, 16, 20, 22, 25, 28, 31, 34, 39], median 23.5. Class A has the higher median.\n\nHint for next time: Read Class A''s leaves outwards from the stem to rebuild its data list.","m":2,"df":"medium","tp":"stem-and-leaf diagrams","st":"back-to-back stem-and-leaf","cfg":{"source":"assess-prep-myp4-formative","question_number":4,"myp_criterion":"D","next_time_hint":"Read Class A''s leaves outwards from the stem to rebuild its data list.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the median mark for Class A.","kind":"numeric","points":1,"hints":["Read Class A''s leaves outwards from the stem to rebuild its data list.","Write A''s marks in order, then take the middle value."],"answer":24,"tolerance":0},{"id":"b","label":"(b)","prompt":"Which class has the higher median? Type: Class A or Class B.","kind":"text","points":1,"hints":["You need both medians before you can compare.","Find Class B''s median the same way, then compare."],"accepted":["Class A","A"]}]}},{"n":5,"t":"assess_parts","p":"A student''s marks in 8 quizzes are: 4, 7, 7, 9, 12, 7, 15, 9.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A student''s marks in 8 quizzes are: 4, 7, 7, 9, 12, 7, 15, 9."}]}]},"e":"Mean = (4+7+7+9+12+7+15+9) ÷ 8 = 70 ÷ 8 = 8.75. Ordered: 4, 7, 7, 7, 9, 9, 12, 15, so the median is (7+9) ÷ 2 = 8. The mode is 7 (it appears three times).\n\nHint for next time: Mean = total of the values ÷ how many there are.","m":2,"df":"easy","tp":"mean, mode and median","st":"mean, median and mode of raw data","cfg":{"source":"assess-prep-myp4-formative","question_number":5,"myp_criterion":"A","next_time_hint":"Mean = total of the values ÷ how many there are.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the mean mark.","kind":"numeric","points":1,"hints":["Mean = total of the values ÷ how many there are.","Add all 8 marks, then divide by 8."],"answer":8.75,"tolerance":0.01},{"id":"b","label":"(b)","prompt":"Find the median mark.","kind":"numeric","points":1,"hints":["Order the data first; with an even count of values the median sits between two of them.","Write the marks in order and average the 4th and 5th values."],"answer":8.0,"tolerance":0}]}},{"n":6,"t":"assess_parts","p":"The table shows the number of goals scored by a team in 20 matches.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The table shows the number of goals scored by a team in 20 matches."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Goals per match (20 matches)","columns":["Goals (x)","Frequency (f)"],"rows":[["0","2"],["1","4"],["2","7"],["3","5"],["4","2"]]}}}]},"e":"Total frequency = 20. Σfx = 41, so the mean = 41 ÷ 20 = 2.05 goals per match.\n\nHint for next time: Add the frequency column.","m":2,"df":"medium","tp":"mean, mode and median","st":"mean from a frequency table","cfg":{"source":"assess-prep-myp4-formative","question_number":6,"myp_criterion":"A","next_time_hint":"Add the frequency column.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the total number of matches recorded in the table.","kind":"numeric","points":1,"hints":["Add the frequency column.","Sum all the frequencies f."],"answer":20,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the mean number of goals per match.","kind":"numeric","points":1,"hints":["For a frequency table the mean is Σfx ÷ Σf.","Multiply each x by its f, add those products, then divide by Σf."],"answer":2.05,"tolerance":0.01}]}},{"n":7,"t":"assess_parts","p":"The table shows the test scores of 20 students.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The table shows the test scores of 20 students."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Test scores","columns":["Score (x)","Frequency (f)"],"rows":[["10","2"],["11","4"],["12","6"],["13","5"],["14","3"]]}}}]},"e":"The modal score is 12 (highest frequency, 6). Cumulative frequencies: 2, 6, 12, 17, 20; the median (10th/11th value) falls in the score 12 group, so the median is 12.\n\nHint for next time: The mode is the value with the greatest frequency.","m":2,"df":"medium","tp":"mean, mode and median","st":"mode and median from a frequency table","cfg":{"source":"assess-prep-myp4-formative","question_number":7,"myp_criterion":"A","next_time_hint":"The mode is the value with the greatest frequency.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write down the modal score.","kind":"numeric","points":1,"hints":["The mode is the value with the greatest frequency.","Find the largest frequency and read off its score."],"answer":12,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find the median score.","kind":"numeric","points":1,"hints":["Build cumulative frequencies to locate the middle values.","The median is the average of the 10th and 11th values; find which score they land on."],"answer":12,"tolerance":0}]}},{"n":8,"t":"assess_parts","p":"The table shows the time (minutes) students spent on homework one evening.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The table shows the time (minutes) students spent on homework one evening."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Homework time","columns":["Time t (min)","Frequency"],"rows":[["0 ≤ t < 10","4"],["10 ≤ t < 20","9"],["20 ≤ t < 30","12"],["30 ≤ t < 40","5"]]}}}]},"e":"Midpoints are 5, 15, 25, 35. Σfx = 630 and Σf = 30, so the estimated mean = 21… ≈ 21.0 minutes. The modal class is 20 ≤ t < 30 (frequency 12).\n\nHint for next time: Grouped data has no exact values — represent each class by one number.","m":2,"df":"medium","tp":"grouped data and estimated mean","st":"estimated mean and modal class","cfg":{"source":"assess-prep-myp4-formative","question_number":8,"myp_criterion":"A","next_time_hint":"Grouped data has no exact values — represent each class by one number.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Calculate an estimate for the mean time. Give your answer to 1 decimal place.","kind":"numeric","points":1,"hints":["Grouped data has no exact values — represent each class by one number.","Use each class midpoint × frequency, then Σfx ÷ Σf."],"answer":21.0,"tolerance":0.06,"unit":"min"},{"id":"b","label":"(b)","prompt":"Write down the modal class. Type it like 20 ≤ t < 30.","kind":"text","points":1,"hints":["The modal class is the class with the greatest frequency.","Find the largest frequency and write its class interval."],"accepted":["20 ≤ t < 30","20-30","20 to 30","20 ≤ t<30","20<t<30"]}]}},{"n":9,"t":"assess_parts","p":"The masses of parcels (kg) are recorded in the grouped table.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The masses of parcels (kg) are recorded in the grouped table."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Mass of parcels","columns":["Mass m (kg)","Frequency"],"rows":[["0 ≤ m < 5","3"],["5 ≤ m < 10","8"],["10 ≤ m < 15","11"],["15 ≤ m < 20","6"],["20 ≤ m < 25","2"]]}}}]},"e":"Cumulative frequencies: 3, 11, 22, 28, 30; the median (15th value) is in 10 ≤ m < 15, the median class. Estimated mean: Σfx ÷ Σf = 355 ÷ 30 = 11.83 ≈ 11.83 kg.\n\nHint for next time: The median class contains the middle value of the data set.","m":2,"df":"medium","tp":"grouped data and estimated mean","st":"median class and estimated mean","cfg":{"source":"assess-prep-myp4-formative","question_number":9,"myp_criterion":"B","next_time_hint":"The median class contains the middle value of the data set.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write down the median class. Type it like 10 ≤ m < 15.","kind":"text","points":1,"hints":["The median class contains the middle value of the data set.","Use cumulative frequencies to find which class holds the 15th value."],"accepted":["10 ≤ m < 15","10-15","10 to 15","10 ≤ m<15"]},{"id":"b","label":"(b)","prompt":"Calculate an estimate for the mean mass. Give your answer to 1 decimal place.","kind":"numeric","points":1,"hints":["Represent each class by its midpoint.","Compute Σfx with the midpoints 2.5, 7.5, 12.5, …, then divide by Σf."],"answer":11.83,"tolerance":0.06,"unit":"kg"}]}},{"n":10,"t":"assess_parts","p":"A gym estimates the mean age of its members from the grouped table: 10 ≤ a < 20 (f = 6), 20 ≤ a < 30 (f = 14), 30 ≤ a < 40 (f = 10).","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A gym estimates the mean age of its members from the grouped table: 10 ≤ a < 20 (f = 6), 20 ≤ a < 30 (f = 14), 30 ≤ a < 40 (f = 10)."}]}]},"e":"Midpoints 15, 25, 35: Σfx = 15×6 + 25×14 + 35×10 = 790; Σf = 30; estimated mean = 790 ÷ 30 = 26.3 years (1 d.p.). The calculation represents every member in a class by the class midpoint.\n\nHint for next time: Each class needs one representative value before you can multiply.","m":2,"df":"medium","tp":"grouped data and estimated mean","st":"why the estimated mean uses midpoints","cfg":{"source":"assess-prep-myp4-formative","question_number":10,"myp_criterion":"D","next_time_hint":"Each class needs one representative value before you can multiply.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Calculate an estimate for the mean age. Give your answer to 1 decimal place.","kind":"numeric","points":1,"hints":["Each class needs one representative value before you can multiply.","Midpoints × frequencies, added, divided by the total frequency."],"answer":26.3,"tolerance":0.06,"unit":"years"},{"id":"b","label":"(b)","prompt":"Which single value represents each class in this estimate? Type the name of the value.","kind":"text","points":1,"hints":["The value sits in the middle of each class interval.","It is the average of the class''s lower and upper bounds."],"accepted":["midpoint","class midpoint","midpoints","the midpoint","mid-point","class mid-point"]}]}},{"n":11,"t":"assess_parts","p":"Here are 10 reaction times (seconds): 3, 5, 6, 8, 9, 11, 12, 14, 15, 18.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Here are 10 reaction times (seconds): 3, 5, 6, 8, 9, 11, 12, 14, 15, 18."}]}]},"e":"Range = 18 − 3 = 15. The median splits the data into 3, 5, 6, 8, 9 and 11, 12, 14, 15, 18, so Q1 = 6 and Q3 = 14. IQR = 14 − 6 = 8.\n\nHint for next time: Range uses only the two extreme values.","m":2,"df":"medium","tp":"range, quartiles and IQR","st":"quartiles and IQR","cfg":{"source":"assess-prep-myp4-formative","question_number":11,"myp_criterion":"A","next_time_hint":"Range uses only the two extreme values.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the range.","kind":"numeric","points":1,"hints":["Range uses only the two extreme values.","Subtract the smallest value from the largest."],"answer":15,"tolerance":0,"unit":"s"},{"id":"b","label":"(b)","prompt":"Find the interquartile range (IQR).","kind":"numeric","points":1,"hints":["IQR measures the spread of the middle half of the data.","Subtract Q1 from Q3, so find Q3 the same way as Q1 first."],"answer":8,"tolerance":0}]}},{"n":12,"t":"assess_parts","p":"Nine students record their travel times (minutes): 12, 15, 14, 13, 16, 15, 14, 13, 42. One value is very different from the rest.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nine students record their travel times (minutes): 12, 15, 14, 13, 16, 15, 14, 13, 42. One value is very different from the rest."}]}]},"e":"Ordered: 12, 13, 13, 14, 14, 15, 15, 16, 42. Range = 42 − 12 = 30 (huge because of the 42). Q1 = 13, Q3 = 15.5, so IQR = 2.5, which ignores the extreme value. The IQR is the measure unaffected by the outlier.\n\nHint for next time: Quartiles come from the ordered middle sections, not the extremes.","m":2,"df":"hard","tp":"range, quartiles and IQR","st":"IQR and outliers (integrated challenge)","cfg":{"source":"assess-prep-myp4-formative","question_number":12,"myp_criterion":"B","next_time_hint":"Quartiles come from the ordered middle sections, not the extremes.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the IQR of the travel times.","kind":"numeric","points":1,"hints":["Quartiles come from the ordered middle sections, not the extremes.","Find Q1 and Q3 from the lower and upper halves, then subtract."],"answer":2.5,"tolerance":0,"unit":"min"},{"id":"b","label":"(b)","prompt":"Which measure of spread is NOT affected by the very large value? Type: range or IQR.","kind":"text","points":1,"hints":["One of these measures uses the extreme values; the other does not.","Ask which measure is built only from the middle half of the data."],"accepted":["IQR","the IQR","interquartile range"]}]}},{"n":13,"t":"assess_parts","p":"A data set has minimum 22 and maximum 45. The eight values are: 22, 25, 28, 31, 34, 37, 40, 45.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A data set has minimum 22 and maximum 45. The eight values are: 22, 25, 28, 31, 34, 37, 40, 45."}]}]},"e":"Ordered as given. Median = (31 + 34) ÷ 2 = 32.5. Lower half 22, 25, 28, 31 → Q1 = 26.5. Upper half 34, 37, 40, 45 → Q3 = 38.5. Five-number summary: 22, 26.5, 32.5, 38.5, 45.\n\nHint for next time: Q1 is the median of the lower half.","m":2,"df":"easy","tp":"five-number summary and box plots","st":"five-number summary","cfg":{"source":"assess-prep-myp4-formative","question_number":13,"myp_criterion":"A","next_time_hint":"Q1 is the median of the lower half.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find Q1.","kind":"numeric","points":1,"hints":["Q1 is the median of the lower half.","Take the middle of 22, 25, 28, 31."],"answer":26.5,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find Q3.","kind":"numeric","points":1,"hints":["Q3 is the median of the upper half.","Take the middle of 34, 37, 40, 45."],"answer":38.5,"tolerance":0}]}},{"n":14,"t":"assess_parts","p":"The box-and-whisker diagram summarises the marks of a class test.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The box-and-whisker diagram summarises the marks of a class test."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"box_plot","title":"Class test marks","xLabel":"Marks","yLabel":"","xMin":0,"xMax":100,"yMin":0,"yMax":1,"fiveNumber":{"min":10,"q1":25,"median":40,"q3":55,"max":80}}}}]},"e":"From the diagram: minimum 10, Q1 25, median 40, Q3 55, maximum 80. IQR = Q3 − Q1 = 55 − 25 = 30.\n\nHint for next time: The median is one of the lines that make the box plot.","m":2,"df":"easy","tp":"five-number summary and box plots","st":"reading a box plot","cfg":{"source":"assess-prep-myp4-formative","question_number":14,"myp_criterion":"A","next_time_hint":"The median is one of the lines that make the box plot.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write down the median mark shown by the diagram.","kind":"numeric","points":1,"hints":["The median is one of the lines that make the box plot.","Find the line drawn inside the box."],"answer":40,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the IQR shown by the diagram.","kind":"numeric","points":1,"hints":["Remember: IQR = Q3 − Q1. First find the quartiles from the box.","The box edges are Q1 and Q3; subtract them."],"answer":30,"tolerance":0}]}},{"n":15,"t":"assess_parts","p":"The table gives the five-number summaries of two classes'' test marks.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The table gives the five-number summaries of two classes'' test marks."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Five-number summaries","columns":["Class","Min","Q1","Median","Q3","Max"],"rows":[["A","42","55","63","71","88"],["B","38","58","64","69","79"]]}}}]},"e":"Class A: 42, 55, 63, 71, 88 → IQR = 71 − 55 = 16. Class B: 38, 58, 64, 69, 79 → IQR = 69 − 58 = 11. Class B has the higher median (64 > 63) and, with the smaller IQR, the more consistent marks.\n\nHint for next time: Compare the middle value of each five-number summary.","m":2,"df":"hard","tp":"five-number summary and box plots","st":"comparing two data sets (integrated challenge)","cfg":{"source":"assess-prep-myp4-formative","question_number":15,"myp_criterion":"D","next_time_hint":"Compare the middle value of each five-number summary.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Which class has the higher median? Type: Class A or Class B.","kind":"text","points":1,"hints":["Compare the middle value of each five-number summary.","Read the median column for both classes."],"accepted":["Class B","B"]},{"id":"b","label":"(b)","prompt":"Which class''s marks are more consistent? Type: Class A or Class B.","kind":"text","points":1,"hints":["Consistency is about spread, not about the median.","Compare the two IQRs — the smaller spread is more consistent."],"accepted":["Class B","B"]}]}},{"n":16,"t":"assess_parts","p":"Complete the cumulative frequency for the masses in the table: 0 ≤ m < 10 (f = 5), 10 ≤ m < 20 (f = 9), 20 ≤ m < 30 (f = 14), 30 ≤ m < 40 (f = 8), 40 ≤ m < 50 (f = 4).","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Complete the cumulative frequency for the masses in the table: 0 ≤ m < 10 (f = 5), 10 ≤ m < 20 (f = 9), 20 ≤ m < 30 (f = 14), 30 ≤ m < 40 (f = 8), 40 ≤ m < 50 (f = 4)."}]}]},"e":"Cumulative frequencies add up as you go: 5, 5 + 9 = 14, 14 + 14 = 28. The number with mass less than 30 kg is the cumulative frequency up to 30, which is 28.\n\nHint for next time: Cumulative means ''add everything so far''.","m":1,"df":"easy","tp":"cumulative frequency","st":"cumulative frequency tables (fill the table)","cfg":{"source":"assess-prep-myp4-formative","question_number":16,"myp_criterion":"A","next_time_hint":"Cumulative means ''add everything so far''.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Cumulative frequency up to 20 ≤ m < 30 is the running total of the first three classes. Type that value in this cell.","kind":"numeric","points":1,"hints":["Cumulative means ''add everything so far''.","Add the frequencies of the first three classes."],"answer":28,"tolerance":0}]}},{"n":17,"t":"assess_parts","p":"The cumulative frequency curve shows the masses of 40 parcels.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The cumulative frequency curve shows the masses of 40 parcels."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"cumulative_curve","title":"Cumulative frequency curve: mass of parcels","xLabel":"Mass (kg)","yLabel":"Cumulative frequency","xMin":0,"xMax":50,"yMin":0,"yMax":40,"points":[[0,0],[10,5],[20,14],[30,28],[40,36],[50,40]]}}}]},"e":"Reading from the curve at cf = 20 (half of 40) gives a median of about 25 kg. Q1 is read at cf = 10 (≈ 17 kg) and Q3 at cf = 30 (≈ 33 kg), so IQR ≈ 33 − 17 = 16 kg. Readings within the stated tolerances are accepted.\n\nHint for next time: Remember: IQR = Q3 − Q1, and the median sits halfway up the curve. First find the total frequency.","m":2,"df":"medium","tp":"cumulative frequency","st":"reading a cumulative frequency curve","cfg":{"source":"assess-prep-myp4-formative","question_number":17,"myp_criterion":"A","next_time_hint":"Remember: IQR = Q3 − Q1, and the median sits halfway up the curve. First find the total frequency.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Estimate the median mass from the curve.","kind":"numeric","points":1,"hints":["Remember: IQR = Q3 − Q1, and the median sits halfway up the curve. First find the total frequency.","Go from half the total frequency across to the curve, then down."],"answer":25,"tolerance":2,"unit":"kg"},{"id":"b","label":"(b)","prompt":"Hence estimate the IQR.","kind":"numeric","points":1,"hints":["You need Q1 as well, read at one-quarter of the total frequency.","Read Q1 at cf = 10, then subtract it from your Q3."],"answer":16,"tolerance":4,"unit":"kg"}]}},{"n":18,"t":"assess_parts","p":"The cumulative frequency curve shows the test marks of 50 students.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The cumulative frequency curve shows the test marks of 50 students."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"cumulative_curve","title":"Cumulative frequency curve: test marks","xLabel":"Mark","yLabel":"Cumulative frequency","xMin":0,"xMax":100,"yMin":0,"yMax":50,"points":[[0,0],[20,6],[40,18],[60,34],[80,46],[100,50]]}}}]},"e":"At 60 marks the curve reads cf = 34, so 34 students scored less than 60. Above 60: 50 − 34 = 16 students. The 80th percentile is the mark at cf = 0.8 × 50 = 40, which reads about 70 marks.\n\nHint for next time: Start from 60 on the mark axis, not from the frequency axis.","m":3,"df":"medium","tp":"cumulative frequency","st":"percentiles and ''how many above''","cfg":{"source":"assess-prep-myp4-formative","question_number":18,"myp_criterion":"D","next_time_hint":"Start from 60 on the mark axis, not from the frequency axis.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many students scored less than 60 marks?","kind":"numeric","points":1,"hints":["Start from 60 on the mark axis, not from the frequency axis.","Go up from 60 to the curve, then across to read the frequency."],"answer":34,"tolerance":2},{"id":"b","label":"(b)","prompt":"How many students scored 60 marks or more?","kind":"numeric","points":1,"hints":["Use the total number of students together with part (a).","Subtract your answer to (a) from the total frequency."],"answer":16,"tolerance":2},{"id":"c","label":"(c)","prompt":"Estimate the 80th percentile mark.","kind":"numeric","points":1,"hints":["A percentile starts from a percentage of the total frequency.","Find 80% of 50 on the frequency axis, then read across and down."],"answer":70,"tolerance":4,"unit":"marks"}]}},{"n":19,"t":"assess_parts","p":"A cumulative frequency curve for the heights of 80 plants passes through (0, 0), (10, 8), (20, 30), (30, 55), (40, 72), (50, 80). The shortest plant was 2 cm and the tallest 48 cm. A box plot is to be drawn from this curve.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A cumulative frequency curve for the heights of 80 plants passes through (0, 0), (10, 8), (20, 30), (30, 55), (40, 72), (50, 80). The shortest plant was 2 cm and the tallest 48 cm. A box plot is to be drawn from this curve."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"cumulative_curve","title":"Cumulative frequency curve: height of plants","xLabel":"Height (cm)","yLabel":"Cumulative frequency","xMin":0,"xMax":50,"yMin":0,"yMax":80,"points":[[0,0],[10,8],[20,30],[30,55],[40,72],[50,80]]}}}]},"e":"Median at cf = 40 → about 26 cm. Q1 at cf = 20 → about 15 cm. Q3 at cf = 60 → about 34 cm. Five-number summary: 2, 15, 26, 34, 48, so IQR ≈ 34 − 15 = 19 cm.\n\nHint for next time: The box of the box plot runs from Q1 to Q3.","m":1,"df":"hard","tp":"cumulative frequency","st":"cumulative curve to box plot (integrated challenge)","cfg":{"source":"assess-prep-myp4-formative","question_number":19,"myp_criterion":"B","next_time_hint":"The box of the box plot runs from Q1 to Q3.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Hence estimate the IQR of the heights.","kind":"numeric","points":1,"hints":["The box of the box plot runs from Q1 to Q3.","Read Q3 at cf = 60, then subtract your Q1."],"answer":19,"tolerance":4,"unit":"cm"}]}},{"n":20,"t":"assess_parts","p":"The histogram shows the number of books read by students in a month (discrete data).","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The histogram shows the number of books read by students in a month (discrete data)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"histogram","title":"Books read in a month","xLabel":"Books","yLabel":"Frequency","xMin":-0.5,"xMax":3.5,"yMin":0,"yMax":10,"bars":[{"from":-0.5,"to":0.5,"height":6},{"from":0.5,"to":1.5,"height":9},{"from":1.5,"to":2.5,"height":5},{"from":2.5,"to":3.5,"height":4}]}}}]},"e":"The bar heights are 6 (0 books), 9 (1 book), 5 (2 books) and 4 (3 books). Total students = 6 + 9 + 5 + 4 = 24.\n\nHint for next time: For discrete data, read the height of the bar over ''1''.","m":2,"df":"easy","tp":"histograms","st":"histogram for discrete data","cfg":{"source":"assess-prep-myp4-formative","question_number":20,"myp_criterion":"A","next_time_hint":"For discrete data, read the height of the bar over ''1''.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many students read exactly 1 book?","kind":"numeric","points":1,"hints":["For discrete data, read the height of the bar over ''1''.","Follow the bar above 1 across to the frequency axis."],"answer":9,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many students are represented altogether?","kind":"numeric","points":1,"hints":["Every bar height is a frequency.","Add the heights of all four bars."],"answer":24,"tolerance":0}]}},{"n":21,"t":"assess_parts","p":"The histogram shows the journey times (continuous data) of 30 commuters, in classes of 10 minutes.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The histogram shows the journey times (continuous data) of 30 commuters, in classes of 10 minutes."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"histogram","title":"Journey times","xLabel":"Time (min)","yLabel":"Frequency","xMin":0,"xMax":50,"yMin":0,"yMax":12,"bars":[{"from":0,"to":10,"height":4},{"from":10,"to":20,"height":8},{"from":20,"to":30,"height":11},{"from":30,"to":40,"height":5},{"from":40,"to":50,"height":2}]}}}]},"e":"Bar heights: 4 (0–10), 8 (10–20), 11 (20–30), 5 (30–40), 2 (40–50). In 20–30 minutes: 11 commuters. Over 30 minutes: 5 + 2 = 7.\n\nHint for next time: With equal class widths, bar height is the frequency.","m":2,"df":"easy","tp":"histograms","st":"histogram for continuous data, equal widths","cfg":{"source":"assess-prep-myp4-formative","question_number":21,"myp_criterion":"A","next_time_hint":"With equal class widths, bar height is the frequency.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many commuters took between 20 and 30 minutes?","kind":"numeric","points":1,"hints":["With equal class widths, bar height is the frequency.","Read the height of the 20–30 bar."],"answer":11,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many commuters took more than 30 minutes?","kind":"numeric","points":1,"hints":["More than 30 means the classes above the 30 boundary.","Add the heights of the bars to the right of 30."],"answer":7,"tolerance":0}]}},{"n":22,"t":"assess_parts","p":"A histogram with unequal class widths shows the waiting times in a clinic. The bar for 0 ≤ t < 10 (width 10) has frequency density 1.2, and the bar for 10 ≤ t < 30 (width 20) has frequency density 0.8. The histogram''s vertical axis is frequency density.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A histogram with unequal class widths shows the waiting times in a clinic. The bar for 0 ≤ t < 10 (width 10) has frequency density 1.2, and the bar for 10 ≤ t < 30 (width 20) has frequency density 0.8. The histogram''s vertical axis is frequency density."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"histogram","title":"Waiting times (frequency density)","xLabel":"Waiting time t (min)","yLabel":"Frequency density","xMin":0,"xMax":30,"yMin":0,"yMax":1.4,"bars":[{"from":0,"to":10,"height":1.2},{"from":10,"to":30,"height":0.8}]}}}]},"e":"Frequency density = frequency ÷ class width, and frequency = density × width. First bar: 1.2 × 10 = 12 patients. Second: 0.8 × 20 = 16 patients.\n\nHint for next time: When widths are unequal, the AREA of a bar gives the frequency.","m":2,"df":"hard","tp":"histograms","st":"unequal widths and frequency density (integrated challenge)","cfg":{"source":"assess-prep-myp4-formative","question_number":22,"myp_criterion":"B","next_time_hint":"When widths are unequal, the AREA of a bar gives the frequency.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many patients waited between 0 and 10 minutes?","kind":"numeric","points":1,"hints":["When widths are unequal, the AREA of a bar gives the frequency.","Multiply the bar''s frequency density by its class width."],"answer":12,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many patients waited between 10 and 30 minutes?","kind":"numeric","points":1,"hints":["Use the same area idea for the wider bar — read its density and width carefully.","Multiply 0.8 by the width of the 10–30 class."],"answer":16,"tolerance":0}]}},{"n":23,"t":"assess_parts","p":"Five athletes record sprint times (seconds): 6, 8, 9, 10, 12.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Five athletes record sprint times (seconds): 6, 8, 9, 10, 12."}]}]},"e":"Mean = 45 ÷ 5 = 9. Deviations: −3, −1, 0, 1, 3; squares sum to 20; variance = 20 ÷ 5 = 4; population standard deviation σ = √4 = 2.\n\nHint for next time: Add the five times and divide by how many there are.","m":2,"df":"medium","tp":"standard deviation","st":"standard deviation of raw data","cfg":{"source":"assess-prep-myp4-formative","question_number":23,"myp_criterion":"A","next_time_hint":"Add the five times and divide by how many there are.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the mean sprint time.","kind":"numeric","points":1,"hints":["Add the five times and divide by how many there are.","The mean is needed before any spread can be measured."],"answer":9,"tolerance":0.01,"unit":"s"},{"id":"b","label":"(b)","prompt":"Calculate the population standard deviation σ. Give your answer to 2 decimal places.","kind":"numeric","points":1,"hints":["Standard deviation measures the typical distance from the mean.","Square each deviation from the mean, average the squares (divide by 5), then square-root."],"answer":2.0,"tolerance":0.02,"unit":"s"}]}},{"n":24,"t":"assess_parts","p":"The frequency table shows the number of emails received per day by 15 workers.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The frequency table shows the number of emails received per day by 15 workers."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Emails per day","columns":["Emails (x)","Frequency (f)"],"rows":[["1","2"],["2","4"],["3","6"],["4","3"]]}}}]},"e":"Mean = 40 ÷ 15 = 2.66667. Σf(x − x̄)² ÷ Σf gives variance 0.8889, so σ = 0.9428 ≈ 0.94.\n\nHint for next time: For a frequency table, weight each value by its frequency.","m":2,"df":"hard","tp":"standard deviation","st":"standard deviation from a frequency table","cfg":{"source":"assess-prep-myp4-formative","question_number":24,"myp_criterion":"A","next_time_hint":"For a frequency table, weight each value by its frequency.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the mean number of emails.","kind":"numeric","points":1,"hints":["For a frequency table, weight each value by its frequency.","Compute Σfx ÷ Σf."],"answer":2.6666666666666665,"tolerance":0.01},{"id":"b","label":"(b)","prompt":"Calculate the population standard deviation σ. Give your answer to 2 decimal places.","kind":"numeric","points":1,"hints":["Extend the deviation method to the table: each squared deviation is weighted too.","Use Σf(x − x̄)² ÷ Σf, then square-root the result."],"answer":0.94,"tolerance":0.02}]}},{"n":25,"t":"assess_parts","p":"Class P''s grouped test marks are in the table. Class Q, whose marks were analysed separately, has a standard deviation of 12.40.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Class P''s grouped test marks are in the table. Class Q, whose marks were analysed separately, has a standard deviation of 12.40."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Class P: grouped marks","columns":["Marks x","Frequency"],"rows":[["0 ≤ x < 10","4"],["10 ≤ x < 20","7"],["20 ≤ x < 30","9"],["30 ≤ x < 40","6"]]}}}]},"e":"Class P midpoints 5, 15, 25, 35 give estimated mean = 21.54 ≈ 21.5 and σ = 9.9778 ≈ 9.98. Class P''s standard deviation (9.98) is smaller than Class Q''s 12.40, so Class P''s marks are less spread out and more consistent.\n\nHint for next time: Grouped data: represent each class by its midpoint, then use the frequency-table method.","m":2,"df":"hard","tp":"standard deviation","st":"standard deviation for grouped data and comparing spread (integrated challenge)","cfg":{"source":"assess-prep-myp4-formative","question_number":25,"myp_criterion":"D","next_time_hint":"Grouped data: represent each class by its midpoint, then use the frequency-table method.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Calculate the population standard deviation σ for Class P, using the class midpoints. Give your answer to 2 decimal places.","kind":"numeric","points":1,"hints":["Grouped data: represent each class by its midpoint, then use the frequency-table method.","Find the estimated mean first, then Σf(midpoint − mean)² ÷ Σf, then square-root."],"answer":9.98,"tolerance":0.03},{"id":"b","label":"(b)","prompt":"Which class is more consistent? Type: Class P or Class Q.","kind":"text","points":1,"hints":["Consistency is judged by spread alone.","The smaller standard deviation is the more consistent class."],"accepted":["Class P","P"]}]}}]'::jsonb) as x
on conflict (id) do nothing;

insert into question_options (id, question_id, label, is_correct, position)
select ('b4000000-0000-4000-8000' || lpad((300000 + (q.config->>'question_number')::int * 100 + (v.idx - 1))::text, 12, '0'))::uuid,
       q.id, v.variant, true, v.idx::int
  from questions q
  cross join lateral jsonb_array_elements_text(q.config->'accepted') with ordinality as v(variant, idx)
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess-prep-myp4-formative'
on conflict (id) do nothing;

insert into quiz_questions (quiz_id, question_id, position, points)
select 'b4000000-0000-4000-8000-000000000001', q.id, (q.config->>'question_number')::int, q.points
  from questions q
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess-prep-myp4-formative'
on conflict (quiz_id, question_id) do nothing;

insert into exams (id, organization_id, quiz_id, class_id, title, description, instructions, duration_minutes, status, access_code, shared_link_enabled, settings, created_by)
values ('b4000000-0000-4000-8000-000000000002', '0a400000-0000-4000-8000-000000000001', 'b4000000-0000-4000-8000-000000000001', '0a400000-0000-4000-8000-000000000109', 'MYP 4 Mathematics — Formative Assessment: Statistics', 'Grade 9 · MYP 4 · Mathematics · Formative (Assess Prep). Statistics only: classification of data, stem-and-leaf diagrams, measures of centre and spread, grouped data, cumulative frequency, histograms and standard deviation. Type every answer — there are no options to choose from.',
  'Type every answer in the box provided — there are no options to choose from. Multi-part questions have a separate box and separate marks for each part. Press the Hint button whenever you are stuck: hints show you the way but never give the answer, and using a hint costs no marks. You have 45 minutes. Your feedback shows the correct answer, a worked solution and a hint for next time for every question.',
  45, 'open', 'MYP4-STATS-2026', true,
  '{"proctoring":false,"require_screen_share":false,"randomize_questions":false,"randomize_options":false,"pass_mark_percent":50,"results_published":true,"access_mode":"shared_link","identity_fields":[],"eligible_class_ids":["0a400000-0000-4000-8000-000000000109"],"attempt_policy":"single_resume","assessment_kind":"formative","grade_level":"9","curriculum":"MYP 4","subject":"Mathematics","total_marks":50,"source":"assess-prep-myp4-formative"}'::jsonb, '3c3ed712-f409-4aa1-a645-816418e22ec4')
on conflict (id) do nothing;

insert into question_hints (id, organization_id, exam_id, question_id, level, body, status, source, created_by, approved_by)
select ('b4000000-0000-4000-8000' || lpad((500000 + (q.config->>'question_number')::int * 10 + h.level)::text, 12, '0'))::uuid,
       '0a400000-0000-4000-8000-000000000001', 'b4000000-0000-4000-8000-000000000002', q.id, h.level, h.body, 'published', 'manual', '3c3ed712-f409-4aa1-a645-816418e22ec4', '3c3ed712-f409-4aa1-a645-816418e22ec4'
  from questions q
  cross join lateral (values
    (1, case when q.type = 'assess_parts'
             then 'Work through the parts in order: later parts often build on earlier ones. Every part also has its own Hint button beside its answer box.'
             else q.config->'hints'->>0 end),
    (2, case when q.type = 'assess_parts'
             then 'For part (a), start here: ' || (q.config->'parts'->0->'hints'->>0)
             else q.config->'hints'->>1 end)
  ) as h(level, body)
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess-prep-myp4-formative'
on conflict (id) do nothing;

